import { describe, expect, it } from 'vitest';
import {
  computeTaskWeights,
  fitHorizon,
  fitHorizonLogistic,
  horizonLift,
  horizonMinutesAtQuantile,
  type HorizonTask,
} from './horizon';
import golden from './horizon-golden.fixture.json';

/**
 * GOLDEN test: the fixture was generated by METR's OWN reference code
 * (`eval-analysis-public/src/horizon`, sklearn LogisticRegression(C=1/reg) at
 * reg=1e-5) over the real HCAST runs for "Claude 3.7 Sonnet (Inspect)". Our pure
 * IRLS port must reproduce METR's coef / intercept / p50 / p80 — proving the fit
 * is faithful (and, as a sanity check, p50 ≈ 63 min matches the paper's
 * ~50–60 min horizon for Claude 3.7 Sonnet). 157 tasks.
 */
describe('fitHorizonLogistic — golden vs METR reference', () => {
  const tasks: HorizonTask[] = golden.tasks.map((t) => ({
    taskId: t.taskId,
    humanMinutes: t.humanMinutes,
    successRate: t.successRate,
    family: t.taskId.split('/')[0],
  }));

  it('reproduces METR equal-weighted coef/intercept/p50/p80', () => {
    // Pass explicit per-task equal weights so weighting is byte-identical to the fixture.
    const withW = tasks.map((t, i) => ({ ...t, weight: golden.tasks[i].weightEqual }));
    const fit = fitHorizonLogistic(withW, { regularization: 1e-5 });
    expect(fit.coef).toBeCloseTo(golden.expected.equal.coef, 4);
    expect(fit.intercept).toBeCloseTo(golden.expected.equal.intercept, 4);
    expect(fit.degenerate).toBe(false);

    const p50 = horizonMinutesAtQuantile(fit, 0.5);
    const p80 = horizonMinutesAtQuantile(fit, 0.8);
    // Within 1% of METR's reference horizons.
    expect(p50).toBeCloseTo(golden.expected.equal.p50, 1);
    expect(p80).toBeCloseTo(golden.expected.equal.p80, 1);
    expect(p50).toBeGreaterThan(p80); // 50%-horizon is always longer than 80%-horizon
  });

  it('reproduces METR invsqrt-weighted coef/intercept/p50/p80', () => {
    const withW = tasks.map((t, i) => ({ ...t, weight: golden.tasks[i].weightInvsqrt }));
    const fit = fitHorizonLogistic(withW, { regularization: 1e-5 });
    expect(fit.coef).toBeCloseTo(golden.expected.invsqrt.coef, 4);
    expect(fit.intercept).toBeCloseTo(golden.expected.invsqrt.intercept, 4);
    expect(horizonMinutesAtQuantile(fit, 0.5)).toBeCloseTo(golden.expected.invsqrt.p50, 1);
    expect(horizonMinutesAtQuantile(fit, 0.8)).toBeCloseTo(golden.expected.invsqrt.p80, 1);
  });

  it("the module's own equal-weighting scheme matches the fixture weights", () => {
    // computeTaskWeights('equal') == 1/n for every task → same as fixture weightEqual.
    const w = computeTaskWeights(tasks, 'equal');
    expect(w.reduce((a, b) => a + b, 0)).toBeCloseTo(1, 10);
    w.forEach((wi, i) => expect(wi).toBeCloseTo(golden.tasks[i].weightEqual, 10));
    const fit = fitHorizonLogistic(tasks, { weighting: 'equal', regularization: 1e-5 });
    expect(fit.coef).toBeCloseTo(golden.expected.equal.coef, 4);
  });
});

describe('computeTaskWeights', () => {
  it('equal weights are 1/n and sum to 1', () => {
    const tasks: HorizonTask[] = [
      { taskId: 'a', humanMinutes: 1, successRate: 1 },
      { taskId: 'b', humanMinutes: 2, successRate: 0 },
      { taskId: 'c', humanMinutes: 4, successRate: 1 },
    ];
    const w = computeTaskWeights(tasks, 'equal');
    expect(w).toEqual([1 / 3, 1 / 3, 1 / 3]);
  });

  it('invsqrt down-weights big families and renormalises to sum 1', () => {
    const tasks: HorizonTask[] = [
      { taskId: 'f1/a', humanMinutes: 1, successRate: 1, family: 'f1' },
      { taskId: 'f1/b', humanMinutes: 2, successRate: 1, family: 'f1' },
      { taskId: 'f1/c', humanMinutes: 4, successRate: 1, family: 'f1' },
      { taskId: 'f2/a', humanMinutes: 8, successRate: 0, family: 'f2' },
    ];
    const w = computeTaskWeights(tasks, 'invsqrt');
    expect(w.reduce((a, b) => a + b, 0)).toBeCloseTo(1, 10);
    // The lone f2 task carries more weight than any single f1 task (1/√1 vs 1/√3).
    expect(w[3]).toBeGreaterThan(w[0]);
  });

  it('explicit per-task weight overrides the scheme', () => {
    const tasks: HorizonTask[] = [
      { taskId: 'a', humanMinutes: 1, successRate: 1, weight: 5 },
      { taskId: 'b', humanMinutes: 2, successRate: 0 },
    ];
    expect(computeTaskWeights(tasks, 'none')[0]).toBe(5);
  });
});

describe('fitHorizonLogistic — degenerate cases', () => {
  it('all-failure → coef −∞, horizon 0, flagged degenerate', () => {
    const tasks: HorizonTask[] = [
      { taskId: 'a', humanMinutes: 1, successRate: 0 },
      { taskId: 'b', humanMinutes: 10, successRate: 0 },
    ];
    const fit = fitHorizonLogistic(tasks);
    expect(fit.coef).toBe(-Infinity);
    expect(fit.degenerate).toBe(true);
    expect(horizonMinutesAtQuantile(fit, 0.5)).toBe(0);
  });

  it('all-success → flagged degenerate, p50 horizon → Infinity', () => {
    const tasks: HorizonTask[] = [
      { taskId: 'a', humanMinutes: 1, successRate: 1 },
      { taskId: 'b', humanMinutes: 10, successRate: 1 },
    ];
    const fit = fitHorizonLogistic(tasks);
    expect(fit.degenerate).toBe(true);
    expect(horizonMinutesAtQuantile(fit, 0.5)).toBe(Infinity);
  });

  it('fewer than 2 distinct human-times → flagged degenerate', () => {
    const tasks: HorizonTask[] = [
      { taskId: 'a', humanMinutes: 5, successRate: 1 },
      { taskId: 'b', humanMinutes: 5, successRate: 0 },
    ];
    const fit = fitHorizonLogistic(tasks);
    expect(fit.degenerate).toBe(true);
    expect(fit.degenerateReason).toMatch(/distinct human-times/);
  });

  it('non-negative slope (success rises with task length) is flagged', () => {
    const tasks: HorizonTask[] = [
      { taskId: 'a', humanMinutes: 1, successRate: 0 },
      { taskId: 'b', humanMinutes: 4, successRate: 0 },
      { taskId: 'c', humanMinutes: 16, successRate: 1 },
      { taskId: 'd', humanMinutes: 64, successRate: 1 },
    ];
    const fit = fitHorizonLogistic(tasks);
    expect(fit.coef).toBeGreaterThanOrEqual(0);
    expect(fit.degenerate).toBe(true);
  });

  it('empty input → degenerate, no throw', () => {
    const fit = fitHorizonLogistic([]);
    expect(fit.degenerate).toBe(true);
    expect(fit.tasks).toBe(0);
  });
});

describe('fitHorizonLogistic — monotonic recovery', () => {
  it('recovers a known sigmoid: harder (longer) tasks fail more, p50 between the regimes', () => {
    // Success collapses around ~16 min: short tasks solved, long tasks not.
    const tasks: HorizonTask[] = [
      { taskId: 't1', humanMinutes: 1, successRate: 1 },
      { taskId: 't2', humanMinutes: 2, successRate: 1 },
      { taskId: 't3', humanMinutes: 4, successRate: 1 },
      { taskId: 't4', humanMinutes: 8, successRate: 0.75 },
      { taskId: 't5', humanMinutes: 16, successRate: 0.5 },
      { taskId: 't6', humanMinutes: 32, successRate: 0.25 },
      { taskId: 't7', humanMinutes: 64, successRate: 0 },
      { taskId: 't8', humanMinutes: 128, successRate: 0 },
    ];
    const fit = fitHorizonLogistic(tasks, { weighting: 'equal' });
    expect(fit.coef).toBeLessThan(0);
    expect(fit.degenerate).toBe(false);
    const p50 = horizonMinutesAtQuantile(fit, 0.5);
    // The 50% crossing should land near the 16-min task where successRate == 0.5.
    expect(p50).toBeGreaterThan(8);
    expect(p50).toBeLessThan(32);
  });
});

describe('horizonMinutesAtQuantile', () => {
  it('rejects quantiles outside (0,1)', () => {
    const fit = fitHorizonLogistic([
      { taskId: 'a', humanMinutes: 1, successRate: 1 },
      { taskId: 'b', humanMinutes: 100, successRate: 0 },
    ]);
    expect(() => horizonMinutesAtQuantile(fit, 0)).toThrow();
    expect(() => horizonMinutesAtQuantile(fit, 1)).toThrow();
  });

  it('p80 horizon is shorter than p50 horizon for a sane fit', () => {
    const tasks: HorizonTask[] = [
      { taskId: 'a', humanMinutes: 1, successRate: 1 },
      { taskId: 'b', humanMinutes: 8, successRate: 0.6 },
      { taskId: 'c', humanMinutes: 64, successRate: 0.1 },
    ];
    const fit = fitHorizonLogistic(tasks);
    expect(horizonMinutesAtQuantile(fit, 0.8)).toBeLessThan(horizonMinutesAtQuantile(fit, 0.5));
  });
});

describe('fitHorizon — CIs are deterministic and bracket the point', () => {
  const tasks: HorizonTask[] = golden.tasks.map((t) => ({
    taskId: t.taskId,
    humanMinutes: t.humanMinutes,
    successRate: t.successRate,
    family: t.taskId.split('/')[0],
  }));

  it('p50 CI brackets the point estimate and reproduces across runs', () => {
    const a = fitHorizon(tasks, { bootstrap: 300, seed: 7, quantiles: [0.5, 0.8] });
    const b = fitHorizon(tasks, { bootstrap: 300, seed: 7, quantiles: [0.5, 0.8] });
    const p50a = a.points.find((p) => p.quantile === 0.5)!;
    const p50b = b.points.find((p) => p.quantile === 0.5)!;
    expect(p50a.ci).toBeDefined();
    expect(p50a.ci!.lower).toBeLessThanOrEqual(p50a.horizonMinutes);
    expect(p50a.ci!.upper).toBeGreaterThanOrEqual(p50a.horizonMinutes);
    // Deterministic: same seed → identical interval.
    expect(p50b.ci!.lower).toBe(p50a.ci!.lower);
    expect(p50b.ci!.upper).toBe(p50a.ci!.upper);
  });

  it('skips CIs when bootstrap=0', () => {
    const r = fitHorizon(tasks, { bootstrap: 0 });
    expect(r.points[0].ci).toBeUndefined();
  });
});

describe('horizonLift — the headline two-arm metric', () => {
  it('computes ratio + minutes; flags CI separation when intervals do not overlap', () => {
    const treatment = { quantile: 0.5, horizonMinutes: 60, ci: { point: 60, lower: 50, upper: 72, ci: 0.95 } };
    const baseline = { quantile: 0.5, horizonMinutes: 30, ci: { point: 30, lower: 24, upper: 38, ci: 0.95 } };
    const lift = horizonLift(treatment, baseline);
    expect(lift.liftRatio).toBeCloseTo(2, 6);
    expect(lift.liftMinutes).toBe(30);
    expect(lift.ciSeparated).toBe(true); // treatment.lower (50) > baseline.upper (38)
  });

  it('ciSeparated is false when intervals overlap', () => {
    const treatment = { quantile: 0.5, horizonMinutes: 40, ci: { point: 40, lower: 30, upper: 55, ci: 0.95 } };
    const baseline = { quantile: 0.5, horizonMinutes: 35, ci: { point: 35, lower: 28, upper: 45, ci: 0.95 } };
    expect(horizonLift(treatment, baseline).ciSeparated).toBe(false);
  });

  it('rejects mismatched quantiles', () => {
    expect(() =>
      horizonLift({ quantile: 0.5, horizonMinutes: 10 }, { quantile: 0.8, horizonMinutes: 5 }),
    ).toThrow();
  });
});
